/* Courses that play, remember where each buyer is, and stay private. A course belongs to a product (public.courses), holds modules (public.course_modules) and lessons (public.course_lessons), and each lesson now has its own video kept in the private digital-products bucket (video_path, video_size, video_mime, video_name; the server writes these, a signed in editor cannot point a lesson at somebody else's file), a captions file (captions_path), a free preview switch (is_preview), a running time (duration_seconds) and its downloads (public.lesson_attachments, written by the server only). Each buyer's place is kept per lesson (public.course_progress: completed_at, last_position_seconds) and per course (public.course_enrollments: the last lesson opened, when, how far through, when it was finished, and the progress emails already sent, so a reminder goes at most once a week and never after the course is done). Who may read what is decided in one place, public.storelib_product_access(): the creator reads and edits their own course; a buyer (an entitlement, or a completed order) reads its modules, lessons and downloads and their own progress; anybody reads module titles and the lessons marked as a free preview of a published course. Progress and enrollments are written by the server only. public.course_outline() gives the product page the titles, running times and preview marks of a published course in one call. Every policy these tables had before is replaced. Tables that already exist keep their rows. Needs part 63 for the guard on the video columns (without it the guard is skipped and the server still refuses a path that is not the creator's own). Safe to run again. */
CREATE TABLE IF NOT EXISTS public.courses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL UNIQUE REFERENCES public.products(id) ON DELETE CASCADE, created_at timestamptz DEFAULT now());
ALTER TABLE public.courses ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
CREATE TABLE IF NOT EXISTS public.course_modules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), course_id uuid NOT NULL REFERENCES public.courses(id) ON DELETE CASCADE, title text NOT NULL, position integer NOT NULL DEFAULT 0, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS public.course_lessons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), module_id uuid NOT NULL REFERENCES public.course_modules(id) ON DELETE CASCADE, title text NOT NULL, position integer NOT NULL DEFAULT 0, content_text text, video_url text, created_at timestamptz DEFAULT now());
ALTER TABLE public.course_lessons ADD COLUMN IF NOT EXISTS video_path text, ADD COLUMN IF NOT EXISTS video_size bigint, ADD COLUMN IF NOT EXISTS video_mime text, ADD COLUMN IF NOT EXISTS video_name text, ADD COLUMN IF NOT EXISTS captions_path text, ADD COLUMN IF NOT EXISTS is_preview boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS duration_seconds integer, ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
CREATE TABLE IF NOT EXISTS public.lesson_attachments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lesson_id uuid NOT NULL REFERENCES public.course_lessons(id) ON DELETE CASCADE, file_path text NOT NULL, file_name text NOT NULL, created_at timestamptz DEFAULT now());
ALTER TABLE public.lesson_attachments ADD COLUMN IF NOT EXISTS file_size bigint, ADD COLUMN IF NOT EXISTS mime_type text, ADD COLUMN IF NOT EXISTS position integer NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS public.course_progress (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), buyer_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, lesson_id uuid NOT NULL REFERENCES public.course_lessons(id) ON DELETE CASCADE, completed boolean DEFAULT false, completed_at timestamptz, created_at timestamptz DEFAULT now(), CONSTRAINT unique_buyer_lesson UNIQUE (buyer_id, lesson_id));
ALTER TABLE public.course_progress ADD COLUMN IF NOT EXISTS course_id uuid REFERENCES public.courses(id) ON DELETE CASCADE, ADD COLUMN IF NOT EXISTS last_position_seconds real NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS duration_seconds real, ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now();
DO $do$ BEGIN IF NOT EXISTS (SELECT 1 FROM pg_index i WHERE i.indrelid = 'public.course_progress'::regclass AND i.indisunique AND (SELECT array_agg(a.attname::text ORDER BY a.attname) FROM pg_attribute a WHERE a.attrelid = i.indrelid AND a.attnum = ANY (i.indkey)) = ARRAY['buyer_id', 'lesson_id']) THEN IF EXISTS (SELECT 1 FROM public.course_progress GROUP BY buyer_id, lesson_id HAVING count(*) > 1) THEN RAISE WARNING 'part 74: a buyer has two progress rows for one lesson, so the one-row-per-lesson key was not added. See them with: select buyer_id, lesson_id, count(*) from public.course_progress group by 1, 2 having count(*) > 1;'; ELSE CREATE UNIQUE INDEX course_progress_buyer_lesson ON public.course_progress (buyer_id, lesson_id); END IF; END IF; END $do$;
CREATE TABLE IF NOT EXISTS public.course_enrollments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), buyer_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, course_id uuid NOT NULL REFERENCES public.courses(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE, last_lesson_id uuid REFERENCES public.course_lessons(id) ON DELETE SET NULL, started_at timestamptz NOT NULL DEFAULT now(), last_opened_at timestamptz NOT NULL DEFAULT now(), last_activity_at timestamptz NOT NULL DEFAULT now(), completed_lessons integer NOT NULL DEFAULT 0, total_lessons integer NOT NULL DEFAULT 0, percent integer NOT NULL DEFAULT 0 CHECK (percent BETWEEN 0 AND 100), completed_at timestamptz, emails_off boolean NOT NULL DEFAULT false, last_nudge_at timestamptz, nudges_sent integer NOT NULL DEFAULT 0, completion_emailed_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (buyer_id, course_id));
CREATE INDEX IF NOT EXISTS idx_course_modules_course ON public.course_modules (course_id, position);
CREATE INDEX IF NOT EXISTS idx_course_lessons_module ON public.course_lessons (module_id, position);
CREATE INDEX IF NOT EXISTS idx_lesson_attachments_lesson ON public.lesson_attachments (lesson_id, position);
CREATE INDEX IF NOT EXISTS idx_course_progress_buyer_course ON public.course_progress (buyer_id, course_id);
CREATE INDEX IF NOT EXISTS idx_course_progress_lesson ON public.course_progress (lesson_id);
CREATE INDEX IF NOT EXISTS course_enrollments_buyer_idx ON public.course_enrollments (buyer_id, last_opened_at DESC);
CREATE INDEX IF NOT EXISTS course_enrollments_nudge_idx ON public.course_enrollments (last_activity_at) WHERE completed_at IS NULL AND emails_off = false;
CREATE INDEX IF NOT EXISTS course_enrollments_finished_idx ON public.course_enrollments (completed_at) WHERE completed_at IS NOT NULL AND completion_emailed_at IS NULL;
ALTER TABLE public.courses ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.course_modules ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.course_lessons ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.lesson_attachments ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.course_progress ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.course_enrollments ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.storelib_product_access(p_product_id uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT CASE WHEN (SELECT auth.uid()) IS NOT NULL AND c.user_id = (SELECT auth.uid()) THEN 'creator' WHEN (SELECT auth.uid()) IS NOT NULL AND (EXISTS (SELECT 1 FROM public.entitlements e WHERE e.product_id = p.id AND e.buyer_id = (SELECT auth.uid())) OR EXISTS (SELECT 1 FROM public.orders o WHERE o.product_id = p.id AND o.buyer_id = (SELECT auth.uid()) AND o.status = 'completed')) THEN 'owner' WHEN p.status = 'published' THEN 'public' ELSE 'none' END FROM public.products p LEFT JOIN public.creators c ON c.id = p.creator_id WHERE p.id = p_product_id $f$;
CREATE OR REPLACE FUNCTION public.storelib_course_access(p_course_id uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT coalesce((SELECT public.storelib_product_access(co.product_id) FROM public.courses co WHERE co.id = p_course_id), 'none') $f$;
CREATE OR REPLACE FUNCTION public.storelib_module_access(p_module_id uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT coalesce((SELECT public.storelib_course_access(m.course_id) FROM public.course_modules m WHERE m.id = p_module_id), 'none') $f$;
CREATE OR REPLACE FUNCTION public.storelib_lesson_access(p_lesson_id uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT coalesce((SELECT CASE WHEN a.level IN ('creator', 'owner') THEN a.level WHEN l.is_preview AND a.level = 'public' THEN 'preview' ELSE 'none' END FROM public.course_lessons l CROSS JOIN LATERAL (SELECT public.storelib_module_access(l.module_id) AS level) a WHERE l.id = p_lesson_id), 'none') $f$;
REVOKE ALL ON FUNCTION public.storelib_product_access(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.storelib_course_access(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.storelib_module_access(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.storelib_lesson_access(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.storelib_product_access(uuid) TO anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.storelib_course_access(uuid) TO anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.storelib_module_access(uuid) TO anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.storelib_lesson_access(uuid) TO anon, authenticated, service_role;
DO $do$ DECLARE p record; BEGIN FOR p IN SELECT policyname, tablename FROM pg_policies WHERE schemaname = 'public' AND tablename IN ('courses', 'course_modules', 'course_lessons', 'lesson_attachments', 'course_progress', 'course_enrollments') LOOP EXECUTE format('DROP POLICY %I ON public.%I', p.policyname, p.tablename); END LOOP; END $do$;
CREATE POLICY courses_read ON public.courses FOR SELECT TO anon, authenticated USING (public.storelib_course_access(id) IN ('creator', 'owner', 'public'));
CREATE POLICY courses_creator_insert ON public.courses FOR INSERT TO authenticated WITH CHECK (public.storelib_product_access(product_id) = 'creator');
CREATE POLICY courses_creator_update ON public.courses FOR UPDATE TO authenticated USING (public.storelib_course_access(id) = 'creator') WITH CHECK (public.storelib_product_access(product_id) = 'creator');
CREATE POLICY courses_creator_delete ON public.courses FOR DELETE TO authenticated USING (public.storelib_course_access(id) = 'creator');
CREATE POLICY course_modules_read ON public.course_modules FOR SELECT TO anon, authenticated USING (public.storelib_course_access(course_id) IN ('creator', 'owner', 'public'));
CREATE POLICY course_modules_creator_insert ON public.course_modules FOR INSERT TO authenticated WITH CHECK (public.storelib_course_access(course_id) = 'creator');
CREATE POLICY course_modules_creator_update ON public.course_modules FOR UPDATE TO authenticated USING (public.storelib_course_access(course_id) = 'creator') WITH CHECK (public.storelib_course_access(course_id) = 'creator');
CREATE POLICY course_modules_creator_delete ON public.course_modules FOR DELETE TO authenticated USING (public.storelib_course_access(course_id) = 'creator');
CREATE POLICY course_lessons_read ON public.course_lessons FOR SELECT TO anon, authenticated USING (public.storelib_module_access(module_id) IN ('creator', 'owner') OR (is_preview AND public.storelib_module_access(module_id) = 'public'));
CREATE POLICY course_lessons_creator_insert ON public.course_lessons FOR INSERT TO authenticated WITH CHECK (public.storelib_module_access(module_id) = 'creator');
CREATE POLICY course_lessons_creator_update ON public.course_lessons FOR UPDATE TO authenticated USING (public.storelib_module_access(module_id) = 'creator') WITH CHECK (public.storelib_module_access(module_id) = 'creator');
CREATE POLICY course_lessons_creator_delete ON public.course_lessons FOR DELETE TO authenticated USING (public.storelib_module_access(module_id) = 'creator');
CREATE POLICY lesson_attachments_read ON public.lesson_attachments FOR SELECT TO authenticated USING (public.storelib_lesson_access(lesson_id) IN ('creator', 'owner'));
CREATE POLICY course_progress_own ON public.course_progress FOR SELECT TO authenticated USING (buyer_id = (SELECT auth.uid()));
CREATE POLICY course_enrollments_own ON public.course_enrollments FOR SELECT TO authenticated USING (buyer_id = (SELECT auth.uid()));
REVOKE INSERT, UPDATE, DELETE ON public.lesson_attachments, public.course_progress, public.course_enrollments FROM anon, authenticated;
DO $do$ BEGIN IF to_regprocedure('public.storelib_keep_server_columns()') IS NULL THEN RAISE NOTICE 'part 74: part 63 has not run, so the lesson video columns are guarded by the server only.'; ELSE DROP TRIGGER IF EXISTS course_lessons_keep_server_columns ON public.course_lessons; CREATE TRIGGER course_lessons_keep_server_columns BEFORE INSERT OR UPDATE ON public.course_lessons FOR EACH ROW EXECUTE FUNCTION public.storelib_keep_server_columns('video_path', 'video_size', 'video_mime', 'video_name', 'captions_path'); END IF; END $do$;
CREATE OR REPLACE FUNCTION public.course_outline(p_product_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'title', m.title, 'lessons', coalesce((SELECT jsonb_agg(jsonb_build_object('id', l.id, 'title', l.title, 'module_id', l.module_id, 'duration_seconds', l.duration_seconds, 'is_preview', l.is_preview, 'has_video', l.video_path IS NOT NULL OR coalesce(l.video_url, '') <> '') ORDER BY l.position, l.created_at) FROM public.course_lessons l WHERE l.module_id = m.id), '[]'::jsonb)) ORDER BY m.position, m.created_at), '[]'::jsonb) FROM public.courses co JOIN public.products p ON p.id = co.product_id JOIN public.course_modules m ON m.course_id = co.id WHERE co.product_id = p_product_id AND (p.status = 'published' OR public.storelib_product_access(p.id) = 'creator') $f$;
REVOKE ALL ON FUNCTION public.course_outline(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.course_outline(uuid) TO anon, authenticated, service_role;
notify pgrst, 'reload schema';
